  $('#stockDock').onclick=e=>{const b=e.target.closest('[data-stock-link]');if(!b)return;prep='stock';api.setTab('prep');paintPrep()};
  $('#soundQuick').onclick=()=>{const s=api.getState();s.sound=!s.sound;api.save();api.beep('choice');api.render()};
  $('#simSpeed').onchange=e=>{const s=api.getState();s.simSpeed=Number(e.target.value)===2?2:1;api.save();api.render()};
