  $('#vnMenuToggle').onclick=event=>{event.stopPropagation();completeVnText();vnMenuOpen=!vnMenuOpen;if(vnMenuOpen)stopVnAuto();drawStory();completeVnText()};
  document.querySelectorAll('[data-week-prop]').forEach(b=>b.onclick=event=>{event.stopPropagation();if(!activeStory.replay&&window.RingWeekStory.choose(state,activeStory.id,b.dataset.weekProp)){save();drawStory();completeVnText();document.querySelector('[data-week-prop="'+b.dataset.weekProp+'"]')?.focus()}beep(activeStory.id==='rana_cup'?'cup':'choice')});
