$('#guideBtn').onclick=()=>{modalOpen=true;$('#app').inert=true;$('#modal').classList.remove('hidden');$('#dialog').innerHTML=`<div class="eyebrow">HOW TO PLAY</div><h2>RiNG 영업 안내</h2><p>1. <strong>준비하기</strong>에서 재료·메뉴·꾸미기를 열 수 있어요. 업무 방식과 재고 현황은 접힌 항목에서 확인하세요.</p><p>2. <strong>영업 시작</strong> 후 주문표에서 제조와 전달을 선택하세요. 자동 우선순위도 선택할 수 있습니다.</p><p>3. 기다림이 길어지면 손님이 떠납니다. 공연 일정과 날씨에 따라 수요가 달라져요. 라이브·특별 공연일에는 한정 세트를 팔 수 있어요.</p><p>4. 정산에서 다음 영업일을 선택하면 아침 이야기가 열려요. 남은 마감 이야기는 스토리 탭에서 볼 수 있어요.</p><div class="actions"><button id="guideClose" class="primary">확인</button></div>`;$('#guideClose').onclick=()=>{modalOpen=false;$('#modal').classList.add('hidden');$('#app').inert=false;render();$('#guideBtn').focus?.()};$('#guideClose').focus?.()};$('#settingsBtn').onclick=()=>{modalOpen=true;$('#app').inert=true;$('#modal').classList.remove('hidden');$('#dialog').innerHTML=`<h2>설정</h2><button id="openBgmSettings">배경 음악 설정</button><div class="card row"><span>효과음</span><button id="sound">${state.sound?'켜짐':'꺼짐'}</button></div><label class="card row" for="volume"><span>효과음 크기</span><input id="volume" type="range" min="0" max="100" value="${Math.round((state.volume??0.2)*100)}"></label><label class="card row" for="readerSpeed"><span>대사 글자 속도</span><select id="readerSpeed"><option value="30" ${(state.vnSpeed??30)===30?'selected':''}>보통</option><option value="12" ${state.vnSpeed===12?'selected':''}>빠르게</option><option value="0" ${state.vnSpeed===0?'selected':''}>즉시</option></select></label><label class="card row" for="autoDelay"><span>자동 진행 간격</span><select id="autoDelay"><option value="1000" ${state.vnAutoDelay===1000?'selected':''}>빠르게</option><option value="1800" ${(state.vnAutoDelay??1800)===1800?'selected':''}>보통</option><option value="3500" ${state.vnAutoDelay===3500?'selected':''}>느리게</option></select></label><label class="card row" for="textSize"><span>대사 글자 크기</span><select id="textSize"><option value="normal" ${state.vnTextSize!=='large'?'selected':''}>보통</option><option value="large" ${state.vnTextSize==='large'?'selected':''}>크게</option></select></label><label class="card row" for="reduceMotion"><span>움직임 줄이기</span><input id="reduceMotion" type="checkbox" ${state.reduceMotion?'checked':''}></label><div class="sound-preview"><span>소리 미리 듣기</span><button data-sample="door">문종</button><button data-sample="brew">커피 추출</button><button data-sample="serve">계산</button><button data-sample="result">정산</button></div><div class="card"><strong>진행 백업</strong><p class="muted">진행은 이 브라우저에 자동 저장됩니다. 다른 브라우저로 옮기거나 보관하려면 백업 파일을 내려받으세요. 복원하면 이 브라우저의 현재 진행을 덮어씁니다.</p><button id="saveExport">백업 내려받기</button> <label class="backup-import" for="restoreFile">백업 파일 복원</label><input id="restoreFile" type="file" accept="application/json,.json"><p id="saveFeedback" class="muted" role="status"></p></div><p class="muted">PROJECT RiNG은 비공식 팬게임입니다.</p><div class="actions"><button id="reset">새 게임</button><button id="done" class="primary">닫기</button></div>`;$('#openBgmSettings').onclick=()=>window.RingTitle?.open('settings');document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>beep(b.dataset.sample));$('#readerSpeed').onchange=e=>{state.vnSpeed=Number(e.target.value);save()};$('#autoDelay').onchange=e=>{state.vnAutoDelay=Number(e.target.value);save()};$('#textSize').onchange=e=>{state.vnTextSize=e.target.value==='large'?'large':'normal';applyPreferences();save()};$('#reduceMotion').onchange=e=>{state.reduceMotion=!!e.target.checked;applyPreferences();save()};$('#saveExport').onclick=exportBackup;$('#restoreFile').onchange=e=>restoreBackup(e.target);$('#volume').oninput=e=>{state.volume=Number(e.target.value)/100;save();beep('cup')};$('#sound').onclick=()=>{state.sound=!state.sound;save();$('#sound').textContent=state.sound?'켜짐':'꺼짐';beep('choice')};$('#done').onclick=()=>{modalOpen=false;$('#modal').classList.add('hidden');$('#app').inert=false;render();$('#settingsBtn').focus?.()};$('#done').focus?.();$('#reset').onclick=()=>{if(confirm('저장된 진행을 지우고 새로 시작할까요?')){if(weekRules)titleNewGame();else{storageMode='ok';clearServiceNotice();state=initial();tab='prep';menuPaused=false;modalOpen=false;$('#modal').classList.add('hidden');$('#app').inert=false;applyPreferences();render()}}}};$('#priority').onchange=e=>{if(['manual','make','serve','rest','pickup'].includes(e.target.value)){state.priority=e.target.value;render(true)}};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));const simulationClock=window.RingClock?.create({speed:()=>state.simSpeed===2?2:1,paused:simulationPaused,session:()=>state,step:tick});if(simulationClock){simulationClock.start();document.addEventListener('visibilitychange',()=>simulationClock.reset())}else setInterval(tick,1000);const quickMode=$('#workModeQuick');if(quickMode)quickMode.onclick=()=>{setTab(state.phase==='open'?'orders':'prep');$('#operations').open=true;$('#priority').focus?.();};const recoveryButton=$('#recoverSave');if(recoveryButton)recoveryButton.onclick=async()=>{try{const raw=localStorage.getItem(KEY+':last-good'),value=JSON.parse(raw);if(!validBackupState(value))throw Error('복구할 정상 저장이 없습니다.');if(!confirm('이전 정상 저장으로 돌아갈까요? 현재 손상 원본은 백업으로 보존합니다.'))return;const damaged=localStorage.getItem(KEY);if(damaged)localStorage.setItem(KEY+':damaged',damaged);await commitSnapshot(readSavedState(value).value);window.location.reload();}catch(error){recoveryButton.textContent=error.message||'저장을 복구하지 못했습니다.';}};
window.RingExperience?.mount({getState:()=>state,render,openDay,setTab,assign,summary,save,beep,selectOrder,replayIntro:()=>showStory('intro',true)});window.RingWeekView?.mount(weekViewAdapter());window.RingCafePresentation?.mount({getState:()=>state,setTab,render});applyPreferences();render();if(window.RingTitle){window.RingTitle.mount(titleAdapter());const menu=$('#systemMenu');if(menu)menu.onclick=()=>window.RingTitle.open()}else if(state.pendingStory&&storyData[state.pendingStory.id])showStory(state.pendingStory.id,false,Math.min(state.pendingStory.index,storyData[state.pendingStory.id].lines.length));else if(state.phase==='closed')summary();



function weekViewAdapter() {
 return {
  state:()=>state, selected:()=>selectedOrderId, render, open:openDay,
  select:selectOrder, notice:serviceNotice, receipt:summary,
  prep:section=>{setTab('prep');window.RingExperience?.choosePrep(section)},
  applyNextPrep,
  assign:(id,kind)=>assign('taki',id,kind),
  linkMilk:id=>{if(state.week.milkOrder!==id)return;const result=weekRules.command(state,id,'make');if(!result)return;state.week.latteLinked=true;state.week.milkOrder=null;beep(result==='make'?'brew':'click');render(true)},
  place:(slot,id)=>{const previous=state.week.placements[slot];if(!weekRules.place(state,slot,id))return false;beep('choice');if(previous!==id&&id==='windowLamp')serviceNotice('타키: 창가 조명이 제법 그럴싸해졌네. 비 오는 날 토모리가 좋아하겠어.');if(previous!==id&&id==='machine')serviceNotice('타키: 오, 추출 속도 1초 빨라졌네! 아논보다 백배 일 잘한다, 이 기계.');render(true);return true},
  undo:()=>{if(!weekRules.undo(state))return false;beep('click');render(true);return true},
  alias:value=>{if(state.phase==='open')return;state.week.alias=Array.from(value.trim()).slice(0,14).join('');render(true)},
  support:requestSupport,
  buy:basket=>{if(!weekRules.buyStock(state,basket))return false;beep('purchase');save();return true},
  cancelQueue:()=>{const job=state.week.nextJob;if(!job)return;state.week.nextJob=null;serviceNotice('#'+job.id+' 예약을 취소했어요. 주문은 대기열에 남아 있어요.','queued');render(true)},
  switchOrder:(id,menu)=>{if(weekRules.switchOrder(state,id,menu)){beep('choice');render(true)}},
  story:id=>{if(state.week.queue.includes(id)&&Object.hasOwn(storyData,id)&&!state.stories.includes(id))showStory(id,false,state.pendingStory?.id===id?state.pendingStory.index:0)}
 };
}

function bindServicePlan(panel) {
 panel.querySelectorAll('[data-plan-kind]').forEach(button=>button.onclick=()=>{
  const {planKind,planValue}=button.dataset;
  const value=planKind==='window'?planValue==='yes':planValue==='none'?null:planValue;
  if(!weekRules.planChoice(state,planKind,value))return;
  render(true);
  panel.querySelector('[data-plan-kind="'+planKind+'"][data-plan-value="'+planValue+'"]')?.focus({preventScroll:true});
 });
}

function applyNextPrep(choice=state.week?.nextPrep) {
 if(!choice||choice.day!==state.day||state.phase!=='prep')return;
 const section=choice.kind==='menu'?'menu':'stock';
 weekViewAdapter().prep(section);
 const target=choice.kind==='work'?$('#priority'):
  choice.kind==='menu'?$('[data-prep-menu="'+choice.id+'"]'):$('#weekBasket [name="'+choice.id+'"]');
 if(!target)return;
 if(choice.kind==='work')$('#operations').open=true;
 const highlight=choice.kind==='stock'?target.closest('label'):target;
 highlight?.classList.add('next-prep-focus');
 target.focus({preventScroll:true});
 target.scrollIntoView?.({block:'nearest'});
}

function showWeekReceipt() {
 if (state.phase!=='closed') return;
 beep('result');
 modalOpen=true;
 $('#app').inert=true;
 $('#modal').classList.remove('hidden');
 const dialog=$('#dialog');
 dialog.innerHTML=window.RingWeekView.receipt(state,storyData);
 window.RingWeekView.bindArchive(dialog,weekViewAdapter());
 $('#tomorrow').onclick=nextDay;
 const mark=$('#weekPlanTomorrow');
 if(mark)mark.onclick=()=>{
  if(state.phase!=='closed')return;
  const action=weekRules.nextAction(state);
  if(!action)return;
  state.week.nextPrep={day:state.day+1,kind:action.kind,id:action.id};
  save();
  mark.textContent='내일 먼저 보기 예약됨';
  mark.setAttribute('aria-pressed','true');
 };
 const reorder=$('#weekReorder');if(reorder)reorder.onclick=()=>{
  const plan=weekRules.recommendation(state,state.day+1);
  dialog.innerHTML='<section class="week-receipt"><div class="eyebrow">DAY '+(state.day+1)+' · 발주 미리 보기</div><h2>내일 필요한 재료</h2><p>오늘 재고와 내일 예보를 기준으로 한 추정량입니다. 실제 발주는 내일 준비 화면에서 할 수 있어요.</p><ul>'+Object.entries(ingredients).map(([key,item])=>'<li>'+item.name+' · 보유 '+state.stock[key]+' · 예상 '+plan.low[key]+'~'+plan.high[key]+'개</li>').join('')+'</ul><button id="done" class="primary">영수증으로</button></section>';
  $('#done').onclick=()=>{showWeekReceipt();$('#weekReorder')?.focus()};$('#done').focus?.();
 };
 $('#weekLook').onclick=()=>{
  modalOpen=false;
  $('#modal').classList.add('hidden');
  $('#app').inert=false;
  render();
  $('#weekScene [data-week="edit"]')?.focus();
 };
 $('#tomorrow').focus?.();
}

function postponeWeekStory() {
 if (!state.week||!activeStory||activeStory.replay||!state.week.queue.includes(activeStory.id)) return;
 stopVnAuto();
 stopVnTyping();
 if(state.pendingStory){state.week.bookmarks ||= {};state.week.bookmarks[activeStory.id]={...state.pendingStory};state.pendingStory=null;save()}
 activeStory=null;
 $('#modal').classList.remove('vn-overlay');
 if(state.phase==='closed')summary();else finishStoryStage(false);
}

